/*! Swiper slim init (Core + Navigation + Pagination) - exposes window.Swiper. Loaded as <script type="module">. */
import Swiper from './swiper-core.min.mjs';
import Navigation from './swiper-navigation.min.mjs';
import Pagination from './swiper-pagination.min.mjs';
Swiper.use([Navigation, Pagination]);
window.Swiper = Swiper;
window.dispatchEvent(new Event('swiper:ready'));
